var h=Math.SQRT2,q=2,x=4,T=1e-12;function S(t){return((t=Math.exp(t))+1/t)/2}function Z(t){return((t=Math.exp(t))-1/t)/2}function j(t){return((t=Math.exp(2*t))-1)/(t+1)}function k(t,c){var f=t[0],l=t[1],n=t[2],m=c[0],Q=c[1],r=c[2],u=m-f,i=Q-l,M=u*u+i*i,s,o;if(M<T)o=Math.log(r/n)/h,s=function(e){return[f+e*u,l+e*i,n*Math.exp(h*e*o)]};else{var v=Math.sqrt(M),g=(r*r-n*n+x*M)/(2*n*q*v),p=(r*r-n*n-x*M)/(2*r*q*v),a=Math.log(Math.sqrt(g*g+1)-g),R=Math.log(Math.sqrt(p*p+1)-p);o=(R-a)/h,s=function(e){var y=e*o,d=S(a),w=n/(q*v)*(d*j(h*y+a)-Z(a));return[f+w*u,l+w*i,n*d/S(h*y+a)]}}return s.duration=o*1e3,s}export{k as i};
